#!/usr/bin/env bash
# Receipts for chapter 18 (signature and tag-object archaeology — cross-repo).
cd "$(dirname "$0")/.."
out=chapters/18-signatures.receipts.md
export LC_ALL=C
g() { desc=$1; cmd=$2; cap=$3; echo '```'; echo "$ $desc"; eval "$cmd" 2>&1 | head -n "$cap"; echo '```'; echo; }
{
echo "# Receipts — ch. 18 signature and tag-object archaeology (cross-repo)"
echo
echo "Verbatim outputs against full clones of openssl, xz, bitcoin, log4j2, linux, go, and cpython."
echo "A PGP armor line proves signature material is embedded in an object; it does not establish key trust."
echo "Regenerate with \`scripts/receipts-18.sh\`. Long outputs are truncated editorially (head or sed)."
echo
echo "## R1 — openssl: the annotated Heartbleed-fix release tag is unsigned"
g "git -C repos/openssl rev-parse refs/tags/OpenSSL_1_0_1g 'refs/tags/OpenSSL_1_0_1g^{}'" "git -C repos/openssl rev-parse refs/tags/OpenSSL_1_0_1g 'refs/tags/OpenSSL_1_0_1g^{}'" 3
g "git -C repos/openssl cat-file -p refs/tags/OpenSSL_1_0_1g" "git -C repos/openssl cat-file -p refs/tags/OpenSSL_1_0_1g" 10
g "git -C repos/openssl tag -v OpenSSL_1_0_1g" "git -C repos/openssl tag -v OpenSSL_1_0_1g" 10
echo "## R2 — openssl: the bounds-check fix is in 1.0.1g; a later tag object contains PGP armor"
g "git -C repos/openssl show -s --format='%H%n%aI%n%an <%ae>%n%s' 96db9023b881d7cd9f379b0c154650d6c108e9a3 'OpenSSL_1_0_1g^{}'" "git -C repos/openssl show -s --format='%H%n%aI%n%an <%ae>%n%s' 96db9023b881d7cd9f379b0c154650d6c108e9a3 'OpenSSL_1_0_1g^{}'" 11
g "git -C repos/openssl merge-base --is-ancestor 96db9023b881d7cd9f379b0c154650d6c108e9a3 'OpenSSL_1_0_1g^{}' && echo 'heartbleed_fix_ancestor_of_release=yes'" "git -C repos/openssl merge-base --is-ancestor 96db9023b881d7cd9f379b0c154650d6c108e9a3 'OpenSSL_1_0_1g^{}' && echo 'heartbleed_fix_ancestor_of_release=yes'" 2
g "git -C repos/openssl rev-parse refs/tags/OpenSSL_1_1_0-pre6 'refs/tags/OpenSSL_1_1_0-pre6^{}'; git -C repos/openssl cat-file -p refs/tags/OpenSSL_1_1_0-pre6 | sed -n '1,6p;/^-----BEGIN PGP SIGNATURE-----$/p'" "git -C repos/openssl rev-parse refs/tags/OpenSSL_1_1_0-pre6 'refs/tags/OpenSSL_1_1_0-pre6^{}'; git -C repos/openssl cat-file -p refs/tags/OpenSSL_1_1_0-pre6 | sed -n '1,6p;/^-----BEGIN PGP SIGNATURE-----$/p'" 10
echo "## R3 — xz: both compromised-release tag objects contain PGP signatures"
g "for tag in v5.6.0 v5.6.1; do git -C repos/xz rev-parse \"refs/tags/\$tag\" \"refs/tags/\$tag^{}\"; git -C repos/xz cat-file -p \"refs/tags/\$tag\" | sed -n '1,6p;/^-----BEGIN PGP SIGNATURE-----$/p'; done" "for tag in v5.6.0 v5.6.1; do git -C repos/xz rev-parse \"refs/tags/\$tag\" \"refs/tags/\$tag^{}\"; git -C repos/xz cat-file -p \"refs/tags/\$tag\" | sed -n '1,6p;/^-----BEGIN PGP SIGNATURE-----$/p'; done" 20
echo "## R4 — xz: those signatures name Git trees that omit the tarball payload path but ignore it"
g "for tag in v5.6.0 v5.6.1; do git -C repos/xz show -s --format=\"\$tag commit=%H tree=%T%n%aI %an <%ae>%n%s\" \"\$tag^{}\"; if git -C repos/xz cat-file -e \"\$tag^{tree}:m4/build-to-host.m4\" 2>/dev/null; then echo \"\$tag m4/build-to-host.m4=present\"; else echo \"\$tag m4/build-to-host.m4=absent\"; fi; git -C repos/xz show \"\$tag^{commit}:m4/.gitignore\" | rg '^build-to-host\\.m4$'; done" "for tag in v5.6.0 v5.6.1; do git -C repos/xz show -s --format=\"\$tag commit=%H tree=%T%n%aI %an <%ae>%n%s\" \"\$tag^{}\"; if git -C repos/xz cat-file -e \"\$tag^{tree}:m4/build-to-host.m4\" 2>/dev/null; then echo \"\$tag m4/build-to-host.m4=present\"; else echo \"\$tag m4/build-to-host.m4=absent\"; fi; git -C repos/xz show \"\$tag^{commit}:m4/.gitignore\" | rg '^build-to-host\\.m4$'; done" 14
g "git -C repos/xz log --all --format='%H' -- m4/build-to-host.m4 | wc -l; git -C repos/xz log --all --format='%H %aI %an <%ae> %s' -S 'build-to-host.m4' -- m4/.gitignore" "git -C repos/xz log --all --format='%H' -- m4/build-to-host.m4 | wc -l; git -C repos/xz log --all --format='%H %aI %an <%ae> %s' -S 'build-to-host.m4' -- m4/.gitignore" 6
echo "## R5 — bitcoin: the signed v0.3.20.2 object calls itself a critical bug-fix release"
g "git -C repos/bitcoin rev-parse refs/tags/v0.3.20.2 'refs/tags/v0.3.20.2^{}'; git -C repos/bitcoin cat-file -p refs/tags/v0.3.20.2 | sed -n '1,6p;/^-----BEGIN PGP SIGNATURE-----$/p'" "git -C repos/bitcoin rev-parse refs/tags/v0.3.20.2 'refs/tags/v0.3.20.2^{}'; git -C repos/bitcoin cat-file -p refs/tags/v0.3.20.2 | sed -n '1,6p;/^-----BEGIN PGP SIGNATURE-----$/p'" 11
g "git -C repos/bitcoin show -s --format='%H%n%aI%n%an <%ae>%n%s' 52248a757b25581339ca6e00cc0da05bfdb04dc8" "git -C repos/bitcoin show -s --format='%H%n%aI%n%an <%ae>%n%s' 52248a757b25581339ca6e00cc0da05bfdb04dc8" 6
echo "## R6 — bitcoin: that exact fix is outside HEAD; an identical patch survives under another hash"
g "git -C repos/bitcoin rev-parse HEAD; if git -C repos/bitcoin merge-base --is-ancestor 52248a757b25581339ca6e00cc0da05bfdb04dc8 HEAD; then echo release_commit_ancestor_of_HEAD=yes; else echo release_commit_ancestor_of_HEAD=no; fi; git -C repos/bitcoin for-each-ref --contains 52248a757b25581339ca6e00cc0da05bfdb04dc8 --format='%(refname) %(objecttype) %(objectname)'" "git -C repos/bitcoin rev-parse HEAD; if git -C repos/bitcoin merge-base --is-ancestor 52248a757b25581339ca6e00cc0da05bfdb04dc8 HEAD; then echo release_commit_ancestor_of_HEAD=yes; else echo release_commit_ancestor_of_HEAD=no; fi; git -C repos/bitcoin for-each-ref --contains 52248a757b25581339ca6e00cc0da05bfdb04dc8 --format='%(refname) %(objecttype) %(objectname)'" 5
g "git -C repos/bitcoin log HEAD -1 --format='%H %aI %an <%ae> %s' --grep='^Make send/receive limits bigger'; for oid in 52248a757b25581339ca6e00cc0da05bfdb04dc8 f36b494aebcfe4cc6a45003520ee7d15eeaba8df; do git -C repos/bitcoin show \"\$oid\" | git patch-id --stable; done" "git -C repos/bitcoin log HEAD -1 --format='%H %aI %an <%ae> %s' --grep='^Make send/receive limits bigger'; for oid in 52248a757b25581339ca6e00cc0da05bfdb04dc8 f36b494aebcfe4cc6a45003520ee7d15eeaba8df; do git -C repos/bitcoin show \"\$oid\" | git patch-id --stable; done" 5
g "git -C repos/bitcoin show --format= --unified=2 52248a757b25581339ca6e00cc0da05bfdb04dc8 -- net.cpp" "git -C repos/bitcoin show --format= --unified=2 52248a757b25581339ca6e00cc0da05bfdb04dc8 -- net.cpp" 24
echo "## R7 — log4j2: three emergency release tag objects, three taggers in eight days"
g "for tag in rel/2.15.0 rel/2.16.0 rel/2.17.0; do git -C repos/log4j2 for-each-ref --format='%(refname:short) tag=%(objectname) target=%(*objectname) %(taggerdate:iso-strict) %(taggername) %(taggeremail) | %(subject)' \"refs/tags/\$tag\"; git -C repos/log4j2 cat-file -p \"refs/tags/\$tag\" | sed -n '1,6p;/^-----BEGIN PGP SIGNATURE-----$/p'; git -C repos/log4j2 show -s --format='target %H%n%aI %an <%ae>%n%s' \"\$tag^{}\"; done" "for tag in rel/2.15.0 rel/2.16.0 rel/2.17.0; do git -C repos/log4j2 for-each-ref --format='%(refname:short) tag=%(objectname) target=%(*objectname) %(taggerdate:iso-strict) %(taggername) %(taggeremail) | %(subject)' \"refs/tags/\$tag\"; git -C repos/log4j2 cat-file -p \"refs/tags/\$tag\" | sed -n '1,6p;/^-----BEGIN PGP SIGNATURE-----$/p'; git -C repos/log4j2 show -s --format='target %H%n%aI %an <%ae>%n%s' \"\$tag^{}\"; done" 34
echo "## R8 — bitcoin: noversion is a signed 2018 policy marker planted on a 2014 commit"
g "git -C repos/bitcoin rev-parse refs/tags/noversion 'refs/tags/noversion^{}'; git -C repos/bitcoin cat-file -p refs/tags/noversion | sed -n '1,10p;/^-----BEGIN PGP SIGNATURE-----$/p'" "git -C repos/bitcoin rev-parse refs/tags/noversion 'refs/tags/noversion^{}'; git -C repos/bitcoin cat-file -p refs/tags/noversion | sed -n '1,10p;/^-----BEGIN PGP SIGNATURE-----$/p'" 14
g "git -C repos/bitcoin show -s --format='%H%n%aI%n%an <%ae>%n%s' aefbf6e30cadaf77ebee44284c74cc5449dc173f; git -C repos/bitcoin describe --tags 'aefbf6e30cadaf77ebee44284c74cc5449dc173f^'; git -C repos/bitcoin describe --tags aefbf6e30cadaf77ebee44284c74cc5449dc173f" "git -C repos/bitcoin show -s --format='%H%n%aI%n%an <%ae>%n%s' aefbf6e30cadaf77ebee44284c74cc5449dc173f; git -C repos/bitcoin describe --tags 'aefbf6e30cadaf77ebee44284c74cc5449dc173f^'; git -C repos/bitcoin describe --tags aefbf6e30cadaf77ebee44284c74cc5449dc173f" 8
echo "## R9 — linux: a merge commit retains a signed mergetag although this clone has no tag refs"
g "git -C repos/linux show -s --format='%H%n%P%n%aI%n%an <%ae>%n%s' 1200d84f4c0a929a0780180d25063d93773be79c" "git -C repos/linux show -s --format='%H%n%P%n%aI%n%an <%ae>%n%s' 1200d84f4c0a929a0780180d25063d93773be79c" 7
g "git -C repos/linux cat-file commit 1200d84f4c0a929a0780180d25063d93773be79c | awk '/^(mergetag| object | type | tag | tagger | -----BEGIN PGP SIGNATURE-----)/ {print}'; git -C repos/linux rev-parse '1200d84f4c0a929a0780180d25063d93773be79c^2'" "git -C repos/linux cat-file commit 1200d84f4c0a929a0780180d25063d93773be79c | awk '/^(mergetag| object | type | tag | tagger | -----BEGIN PGP SIGNATURE-----)/ {print}'; git -C repos/linux rev-parse '1200d84f4c0a929a0780180d25063d93773be79c^2'" 9
g "printf 'tag_refs='; git -C repos/linux for-each-ref refs/tags --format='%(refname)' | wc -l; git -C repos/linux for-each-ref --format='%(refname) %(objecttype) %(objectname)'" "printf 'tag_refs='; git -C repos/linux for-each-ref refs/tags --format='%(refname)' | wc -l; git -C repos/linux for-each-ref --format='%(refname) %(objecttype) %(objectname)'" 4
echo "## R10 — go: 71,792 reachable commits have no Git signature, and all 491 tags are lightweight"
g "printf 'all_commits='; git -C repos/go rev-list --all --count; git -C repos/go log --all --format='%G?' | sort | uniq -c; git -C repos/go for-each-ref refs/tags --format='%(objecttype)' | sort | uniq -c; printf 'tag_refs='; git -C repos/go for-each-ref refs/tags --format='%(refname)' | wc -l" "printf 'all_commits='; git -C repos/go rev-list --all --count; git -C repos/go log --all --format='%G?' | sort | uniq -c; git -C repos/go for-each-ref refs/tags --format='%(objecttype)' | sort | uniq -c; printf 'tag_refs='; git -C repos/go for-each-ref refs/tags --format='%(refname)' | wc -l" 6
g "git -C repos/go for-each-ref refs/tags/weekly.2009-11-06 refs/tags/go1.27rc3 --format='%(refname:short) %(objecttype) %(objectname) %(creatordate:iso-strict) %(authorname) %(authoremail) | %(subject)'; git -C repos/go tag -v go1.27rc3; echo verify_exit=\$?" "git -C repos/go for-each-ref refs/tags/weekly.2009-11-06 refs/tags/go1.27rc3 --format='%(refname:short) %(objecttype) %(objectname) %(creatordate:iso-strict) %(authorname) %(authoremail) | %(subject)'; git -C repos/go tag -v go1.27rc3; echo verify_exit=\$?" 6
echo "## R11 — cpython: tag object 2.0 was made in 2017 for a branch closed in 2011"
g "git -C repos/cpython cat-file -t 1f73a4e1379223ff2e9a8fbed0a62222b6d0eda5; git -C repos/cpython cat-file -p 1f73a4e1379223ff2e9a8fbed0a62222b6d0eda5 | sed -n '1,6p;/^-----BEGIN PGP SIGNATURE-----$/p'; TZ=Etc/GMT+4 date --date=@1497830728 '+tagger_time=%Y-%m-%dT%H:%M:%S%z'" "git -C repos/cpython cat-file -t 1f73a4e1379223ff2e9a8fbed0a62222b6d0eda5; git -C repos/cpython cat-file -p 1f73a4e1379223ff2e9a8fbed0a62222b6d0eda5 | sed -n '1,6p;/^-----BEGIN PGP SIGNATURE-----$/p'; TZ=Etc/GMT+4 date --date=@1497830728 '+tagger_time=%Y-%m-%dT%H:%M:%S%z'" 11
g "git -C repos/cpython show -s --format='%H%n%aI%n%an <%ae>%n%s' 2a9b0a93091b9ef7350a94bb3d3f1c43725b7a8c; if git -C repos/cpython merge-base --is-ancestor 2a9b0a93091b9ef7350a94bb3d3f1c43725b7a8c af49df919dafc3767ae956767dce0482f9cd6d4e; then echo tag_target_ancestor_of_main=yes; else echo tag_target_ancestor_of_main=no; fi; if git -C repos/cpython show-ref --verify --quiet refs/tags/2.0; then echo 'refs/tags/2.0=present'; else echo 'refs/tags/2.0=absent (tag object retained by object ID)'; fi" "git -C repos/cpython show -s --format='%H%n%aI%n%an <%ae>%n%s' 2a9b0a93091b9ef7350a94bb3d3f1c43725b7a8c; if git -C repos/cpython merge-base --is-ancestor 2a9b0a93091b9ef7350a94bb3d3f1c43725b7a8c af49df919dafc3767ae956767dce0482f9cd6d4e; then echo tag_target_ancestor_of_main=yes; else echo tag_target_ancestor_of_main=no; fi; if git -C repos/cpython show-ref --verify --quiet refs/tags/2.0; then echo 'refs/tags/2.0=present'; else echo 'refs/tags/2.0=absent (tag object retained by object ID)'; fi" 10
} > "$out"
echo "wrote $out ($(wc -l < "$out") lines)"
